DROP TABLE IF EXISTS `v_ia_asistencias`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_ia_asistencias` AS select `a`.`id` AS `asistencia_id`,`a`.`socio_id` AS `socio_id`,concat(`s`.`nombres`,' ',`s`.`apellidos`) AS `socio`,`a`.`ingreso` AS `ingreso`,cast(`a`.`ingreso` as date) AS `dia`,hour(`a`.`ingreso`) AS `hora`,(weekday(`a`.`ingreso`) + 1) AS `dia_semana`,`a`.`salida` AS `salida`,timestampdiff(MINUTE,`a`.`ingreso`,`a`.`salida`) AS `duracion_min`,`a`.`metodo` AS `metodo` from (`asistencias` `a` join `socios` `s` on((`s`.`id` = `a`.`socio_id`)));

