CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_ia_detalle_ventas` AS select `d`.`venta_id` AS `venta_id`,`v`.`fecha` AS `fecha`,cast(`v`.`fecha` as date) AS `dia`,`pr`.`id` AS `producto_id`,`pr`.`codigo` AS `codigo`,`pr`.`nombre` AS `producto`,coalesce(`pr`.`categoria`,'Sin categoría') AS `categoria`,`d`.`cantidad` AS `cantidad`,`d`.`precio` AS `precio_unitario`,(`d`.`cantidad` * `d`.`precio`) AS `importe`,(`d`.`cantidad` * (`d`.`precio` - `pr`.`precio_compra`)) AS `utilidad`,`v`.`metodo` AS `metodo` from ((`venta_detalle` `d` join `ventas` `v` on((`v`.`id` = `d`.`venta_id`))) join `productos` `pr` on((`pr`.`id` = `d`.`producto_id`)));

