CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_ia_evaluaciones` AS select `ev`.`id` AS `evaluacion_id`,concat(`s`.`nombres`,' ',`s`.`apellidos`) AS `socio`,`ev`.`fecha` AS `fecha`,`ev`.`peso` AS `peso`,`ev`.`talla` AS `talla`,round((`ev`.`peso` / (`ev`.`talla` * `ev`.`talla`)),1) AS `imc`,`ev`.`grasa` AS `porcentaje_grasa`,`ev`.`cintura` AS `cintura`,`ev`.`pecho` AS `pecho`,`ev`.`brazo` AS `brazo`,`ev`.`pierna` AS `pierna` from (`evaluaciones` `ev` join `socios` `s` on((`s`.`id` = `ev`.`socio_id`)));

