-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `v_ia_membresias`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_ia_membresias` AS select `m`.`id` AS `membresia_id`,`m`.`socio_id` AS `socio_id`,concat(`s`.`nombres`,' ',`s`.`apellidos`) AS `socio`,`p`.`nombre` AS `plan`,`m`.`fecha_inicio` AS `fecha_inicio`,`m`.`fecha_fin` AS `fecha_fin`,`m`.`precio` AS `precio`,`m`.`descuento` AS `descuento`,(`m`.`precio` - `m`.`descuento`) AS `total`,(select coalesce(sum(`pg`.`monto`),0) from `pagos` `pg` where (`pg`.`membresia_id` = `m`.`id`)) AS `pagado`,((`m`.`precio` - `m`.`descuento`) - (select coalesce(sum(`pg`.`monto`),0) from `pagos` `pg` where (`pg`.`membresia_id` = `m`.`id`))) AS `saldo`,`m`.`estado` AS `estado`,((`m`.`estado` <> 'cancelada') and (`m`.`fecha_inicio` <= curdate()) and (`m`.`fecha_fin` >= curdate())) AS `vigente`,`m`.`created_at` AS `creada_en` from ((`membresias` `m` join `socios` `s` on((`s`.`id` = `m`.`socio_id`))) join `planes` `p` on((`p`.`id` = `m`.`plan_id`)));

