-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `v_ia_socios`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_ia_socios` AS select `x`.`socio_id` AS `socio_id`,`x`.`codigo` AS `codigo`,`x`.`dni` AS `dni`,`x`.`nombres` AS `nombres`,`x`.`apellidos` AS `apellidos`,`x`.`socio` AS `socio`,`x`.`genero` AS `genero`,`x`.`fecha_nacimiento` AS `fecha_nacimiento`,`x`.`edad` AS `edad`,`x`.`telefono` AS `telefono`,`x`.`email` AS `email`,`x`.`objetivo` AS `objetivo`,`x`.`fecha_registro` AS `fecha_registro`,`x`.`estado` AS `estado`,`x`.`plan_actual` AS `plan_actual`,`x`.`vence` AS `vence`,`x`.`visitas_30d` AS `visitas_30d`,`x`.`ultima_visita` AS `ultima_visita`,(case when (`x`.`vence` is null) then 'sin_membresia' when (`x`.`vence` >= curdate()) then 'vigente' else 'vencida' end) AS `estado_membresia`,(to_days(`x`.`vence`) - to_days(curdate())) AS `dias_para_vencer` from (select `s`.`id` AS `socio_id`,`s`.`codigo` AS `codigo`,`s`.`dni` AS `dni`,`s`.`nombres` AS `nombres`,`s`.`apellidos` AS `apellidos`,concat(`s`.`nombres`,' ',`s`.`apellidos`) AS `socio`,`s`.`genero` AS `genero`,`s`.`fecha_nacimiento` AS `fecha_nacimiento`,timestampdiff(YEAR,`s`.`fecha_nacimiento`,curdate()) AS `edad`,`s`.`telefono` AS `telefono`,`s`.`email` AS `email`,`s`.`objetivo` AS `objetivo`,`s`.`fecha_registro` AS `fecha_registro`,`s`.`estado` AS `estado`,(select `p`.`nombre` from (`membresias` `m` join `planes` `p` on((`p`.`id` = `m`.`plan_id`))) where ((`m`.`socio_id` = `s`.`id`) and (`m`.`estado` <> 'cancelada')) order by `m`.`fecha_fin` desc,`m`.`id` desc limit 1) AS `plan_actual`,(select max(`m`.`fecha_fin`) from `membresias` `m` where ((`m`.`socio_id` = `s`.`id`) and (`m`.`estado` <> 'cancelada'))) AS `vence`,(select count(0) from `asistencias` `a` where ((`a`.`socio_id` = `s`.`id`) and (`a`.`ingreso` >= (now() - interval 30 day)))) AS `visitas_30d`,(select max(`a`.`ingreso`) from `asistencias` `a` where (`a`.`socio_id` = `s`.`id`)) AS `ultima_visita` from `socios` `s`) `x`;

